    "role": "user",
    "parts": [{
      "text": "HISTÓRICO RECENTE:\n{{ $json.hasHistory ? $json.historyLines : 'Sem histórico anterior.' }}\n\nNOVA PERGUNTA DO CLIENTE:\n{{ $json.originalMessage }}\n\nPERGUNTA REFORMULADA:"
    }]
  }],
  "generationConfig": { "temperature": 0, "maxOutputTokens": 128 }
