// Extrai pergunta reformulada e mantém todos os dados do fluxo
const geminiResp = $input.first().json;
const contextData = $('Preparar Contexto Histórico').first().json;

const reformulada = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text?.trim()
  || contextData.originalMessage;

return [{
  json: {
    ...contextData,
    message: reformulada,           // sobrescreve message com versão enriquecida
    messageOriginal: contextData.originalMessage  // preserva original para o log
  }
}];

// Higienizador de tabelas extraídas de PDF
// PDFs de tabelas costumam gerar texto com espaços extras, colunas embaralhadas
// e números sem contexto. Este nó limpa e reestrutura antes de vetorizar.

const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData || {})[0] || 'file';
const fileName = binaryData?.[binaryKey]?.fileName || 'tabela-longview';
const fileNameClean = fileName.replace(/\.(pdf|csv|txt)$/i, '');
const tipoDoc = $input.first().json['Tipo de documento'] || 'Documento';

// O texto será extraído pelo nó Ler PDF — aqui só preparamos os metadados
return [{
  json: {
    source: fileNameClean,
    fileName: fileName,
    tipoDoc: tipoDoc,
    isStructured: true,
    uploadedAt: new Date().toISOString()
  },
  binary: binaryData
}];

// Recebe o texto extraído do PDF e higieniza para tabelas
// Aplicado DEPOIS do Ler PDF via nó sub-workflow ou code
const items = $input.all();
return items.map(item => {
  let text = item.json.text || item.json.pageContent || '';
  const source = $('Preparar Metadados Tabela').first().json.source;
  const tipoDoc = $('Preparar Metadados Tabela').first().json.tipoDoc;

  // 1. Remove espaços múltiplos deixados por colunas de PDF
  text = text.replace(/[ \t]{2,}/g, ' | ');

  // 2. Remove linhas em branco consecutivas
  text = text.replace(/\n{3,}/g, '\n\n');

  // 3. Remove caracteres de lixo comuns em PDFs de tabela
  text = text.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '');

  // 4. Adiciona prefixo de contexto em cada chunk (ajuda a IA a saber o que é)
  text = `[${tipoDoc} — ${source}]\n${text}`;

  return {
    json: {
      ...item.json,
      text: text.trim(),
      pageContent: text.trim(),
      source: source,
      tipoDoc: tipoDoc
    }
  };
});
